 b=p.chromium.launch(executable_path=CHROMIUM,headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':375,'height':812},reduced_motion='reduce');c.add_init_script('''window.__sounds=[];const start=AudioBufferSourceNode.prototype.start,stop=AudioBufferSourceNode.prototype.stop;AudioBufferSourceNode.prototype.start=function(...a){this.__entry={when:a[0]};window.__sounds.push(this.__entry);return start.apply(this,a)};AudioBufferSourceNode.prototype.stop=function(...a){if(this.__entry)this.__entry.stop=a[0];return stop.apply(this,a)}''');page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));seed(page,'guitar6','degree-5-find')
